    headlineBlurb: "对比现有 silver-ion、silver-chloride 及季铵盐后整理。更少的活性物质意味着更少的原料、更少的水洗废液、更少的废水处理负荷,以及在每个后续生命周期阶段更少的下游环境释放。",
    badgeOekoTex: "OEKO-TEX Std 100 · Class I",
    badgeBluesign: "bluesign® approved",
    badgeEPA: "EPA 联邦注册",
    badgePFASfree: "无 PFAS",
    esgTitle: "这在您的 ESG / 可持续性报告中意味着什么",
    esgBullet1Title: "循环原料声明",
    esgBullet1Text: " —— FUZE 由报废电子产品生产,支持您的循环经济承诺。",
    esgBullet2Title: "可净零生产",
    esgBullet2Text: " —— 生产单元兼容太阳能,支持供应链上游的可再生能源承诺。",
    esgBullet3Title: "水洗废液中零金属释放",
