    certOekoBody: "认证可直接接触皮肤——包括婴儿与贴身衣物。",
    certBluesignTitle: "bluesign® 认证",
    certBluesignBody: "依据 bluesign 标准，对工人、消费者和环境均经验证安全。",
    certPfasTitle: "无 PFAS",
