    jabTitle: "为何我们首选 ASTM E2149",
    jabBody: "我们以 ASTM E2149 为主要测试方法，因为它是为非浸出型抗菌剂设计的。竞争对手采用 AATCC 100 的化学品依赖该测试是因为其叠层几何结构有助于浸出离子在层间扩散——该测试在构造上偏向浸出型。FUZE 在设计上不浸出。请在正确的测试上与我们较量。",
